/****************************************************************************************************/
/* Program ID  : DM0003_GET_ITEM_BY_DIVISION_POP                                                 */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/10/24  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 20181205 nick name 조회요청으로 수정                                                             */
/* 2024/08/29	KJJ			[PJ2024-50461] Team Mapping*/
/*                                                                                                  */
/****************************************************************************************************/

/*****************************************************************************************************
 ※ 작성 Rule 
   1. 대문자, 소문자
      - 테이블, 컬럼, 변수는 소문자로 작성하고, 그 이외는 대문자로 통일
   2. Naming Rule - Prefix
      - 파라메터 : @p_
      - 변수 : 데이타 타입에 따라 @v_(문자), @n_(숫자), @d_(날짜)
   3. 들여쓰기 : 2 space
   4. 기타
      - SQL 수직 배치 : SQL 구문의 세로줄(왼쪽)로 맞춤, 컬럼이나 변수도 KEYWORD 이후 왼쪽 정렬
      - 콤마로 분리된 ID 가 여러 줄에 걸쳐 나올 때, 콤마를 라인의 처음에 위치
******************************************************************************************************/
CREATE PROCEDURE [dbo].[DMF0002_GET_ITEM_BY_SMALLDIVISION_POPUPEx]  
  @p_division_id   NVARCHAR(MAX),
  @p_dept_id        NVARCHAR(MAX),	--Department
  @p_end_customer   NVARCHAR(MAX),	--Endcustomer
  @p_project_code  NVARCHAR(MAX),
  @p_scm_site_id   NVARCHAR(MAX),
  @p_item_id       NVARCHAR(MAX),
  @p_item_type     NVARCHAR(MAX)
AS
BEGIN
	
  SET NOCOUNT ON;
  
  /*  
  SELECT I.DIVISION_ID
     , I.DIVISION_NAME
     , D.PROJECT_CODE
     , A.PROJECT_NAME
     , S.SCM_SITE_ID
     , S.SITE_DESCRIPTION
     , D.ITEM_ID	 
	 , T.ITEM_NAME
	 , T.ITEM_TYPE
	 , ITEM_TYPE_CODE.NAME AS ITEM_TYPE_NAME
	 , T.NICK_NAME
	 , T.ITEM_CLASS_NAME
	 , TEAM.DEPT_ID
	 , TEAM.DEPT_NAME_KO
	 , C.END_CUSTOMER
	 , D.CURRENCY

  FROM   (SELECT * FROM [dbo].[SCM_MST_DIVISION] WITH(NOLOCK) WHERE VALID_YN='Y') AS  I 
       LEFT JOIN (SELECT * FROM [dbo].[SCM_MST_SITE_ITEM] WITH(NOLOCK) WHERE VALID_YN='Y') AS D 
	   ON I.DIVISION_ID  = D.DIVISION_ID
       LEFT JOIN (SELECT * FROM [dbo].[SCM_MST_PROJECT] WITH(NOLOCK)) AS A 
	   ON D.PROJECT_CODE = A.PROJECT_CODE
       LEFT JOIN (SELECT * FROM [dbo].[SCM_MST_SITE] WITH(NOLOCK) WHERE VALID_YN='Y') S 
	   ON D.SCM_SITE_ID  = S.SCM_SITE_ID
	   --LEFT JOIN [dbo].[SCM_MST_ITEM_SN]     T WITH(NOLOCK)
	   LEFT JOIN [dbo].DM_MST_ITEM_SINGLE_V     T WITH(NOLOCK)
	   ON I.DIVISION_ID  = T.DIVISION_ID AND    D.ITEM_ID      = T.ITEM_ID
	   LEFT JOIN (SELECT DISTINCT DIVISION_ID, SCM_SITE_ID, DEPT_ID, END_CUSTOMER FROM SCM_MST_SITE WITH(NOLOCK) WHERE VALID_YN = 'Y') AS C 
	   ON I.DIVISION_ID = C.DIVISION_ID AND D.SCM_SITE_ID = C.SCM_SITE_ID
	   LEFT JOIN (SELECT * FROM SCM_MST_SSO_DEPT_INFO WITH(NOLOCK) WHERE VALID_YN = 'Y')  AS TEAM			       
	   ON C.DEPT_ID = TEAM.DEPT_ID
	   LEFT JOIN (
					SELECT  LOOKUP_CODE AS CODE, [DESCRIPTION] AS NAME
					FROM [dbo].[SCM_ADM_LOOKUP_VALUES] WITH(NOLOCK) 
					WHERE
					VALID_YN ='Y' 
					AND LOOKUP_TYPE = 'ITEM_TYPE_CODE'
	   )  AS ITEM_TYPE_CODE			       
	   ON T.ITEM_TYPE = ITEM_TYPE_CODE.CODE
	   

WHERE 
        CASE WHEN @p_division_id =

                ELSE A.DIVISION_ID
	       END  IN (SELECT t.c.value(''.'', ''NVARCHAR(4000)'')
                    FROM   (SELECT x = CAST(''<t>'' + REPLACE(N''[@p_division_id]'', '','', ''</t><t>'') + ''</t>'' AS xml)) b
                    CROSS APPLY x.nodes(''/t'') t(c)
	               )
    AND    CASE WHEN N''[@p_site_id]'' = ''ALL'' THEN ''ALL''
                ELSE A.SCM_SITE_ID
	       END  IN (SELECT t.c.value(''.'', ''NVARCHAR(4000)'')
                    FROM   (SELECT x = CAST(''<t>'' + REPLACE(N''[@p_site_id]'', '','', ''</t><t>'') + ''</t>'' AS xml)) b
                    CROSS APPLY x.nodes(''/t'') t(c)
	               )     
	GROUP BY A.DIVISION_ID
           , B.END_CUSTOMER
           , A.SCM_SITE_ID
  '; 
  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_iteration]'  , @v_iteration);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_from_yyyymm]', @p_from_yyyymm);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_to_yyyymm]'  , @p_to_yyyymm);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_division_id]', @p_division_id);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_site_id]'    , @p_site_id); 

  --SET @p_debug = @v_sql_text;
  --RETURN @p_debug;
    
  EXEC SP_EXECUTESQL @v_sql_text; 
								  
END

/****************************************************************************************************/
/* Program ID  : DMF0002_GET_MONTH_TO_WEEK_DATA                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/11/15  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/*                                                                                                  */
/****************************************************************************************************/
CREATE PROCEDURE [dbo].[DMF0002_GET_MONTH_TO_WEEK_DATA]
  @p_division_id  NVARCHAR(30),
  @p_site_id      NVARCHAR(30),
  @p_from_yyyymm  NVARCHAR(6),
  @p_to_yyyymm    NVARCHAR(6)
  --@p_debug        NVARCHAR(4000) OUTPUT
AS  
  
BEGIN
  SET NOCOUNT ON;

  DECLARE @v_sql_text       AS NVARCHAR(MAX);
  DECLARE @v_iteration      AS NVARCHAR(MAX);
  DECLARE @v_column_text    AS NVARCHAR(1000);
  DECLARE @v_column_name    AS NVARCHAR(50);
  DECLARE @v_weekstart_date AS NVARCHAR(8);
  DECLARE @p_param_list     AS NVARCHAR(4000);
  DECLARE @p_end_week       AS NVARCHAR(6);
  
  DECLARE c_bucket CURSOR FAST_FORWARD FOR
    SELECT 'W_' + C.BASIS_START_DATE + '_' + CASE WHEN C.BASIS_START_DATE > CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) 
                                                THEN 'UNLOCK_' + CONVERT(CHAR(1), ROW_NUMBER() OVER(PARTITION BY C.month_name  ORDER BY C.month_name ASC))
		  							          ELSE 'LOCK_' + CONVERT(CHAR(1), ROW_NUMBER() OVER(PARTITION BY month_name  ORDER BY month_name ASC))
			  							 END   AS column_name       
         , C.BASIS_START_DATE
    FROM   [dbo].[SCM_SYS_CALENDAR_M] C WITH(NOLOCK)	
    WHERE  C.basis_yyyymm >= @p_from_yyyymm --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
    AND    C.basis_yyyymm <= @p_to_yyyymm   --CONVERT(CHAR(6), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
    GROUP BY C.BASIS_START_DATE
           , C.BASIS_END_DATE
           , C.week_name
           , C.month_name                                  
           --, C.start_yyyymmdd
           --, C.end_yyyymmdd
	;
	
  SELECT @v_iteration = '';

  OPEN c_bucket;
  FETCH NEXT FROM c_bucket INTO @v_column_name, @v_weekstart_date
  WHILE @@FETCH_STATUS = 0   
  BEGIN

	SET @v_column_text = ', SUM(CASE WHEN A.YYYYMMDD = ''[@v_weekstart_date]'' THEN A.BUCKET_PER ELSE '''' END) AS [@v_column_name] ';
	
	SET @v_column_text = REPLACE(@v_column_text,'[@v_weekstart_date]', @v_weekstart_date);
	SET @v_column_text = REPLACE(@v_column_text,'[@v_column_name]', @v_column_name);

	SELECT @v_iteration = @v_iteration + @v_column_text;	
    
    FETCH NEXT FROM c_Bucket INTO @v_column_name, @v_weekstart_date
  END;
  
  --SELECT @v_iteration AS xxxx;

  CLOSE c_bucket;  
  DEALLOCATE c_bucket;

  SET @v_sql_text = '
    SELECT A.DIVISION_ID
         , B.END_CUSTOMER
      	 , A.SCM_SITE_ID
         [@v_iteration]    
    FROM   [dbo].[DM_MST_BUCKET_CONVERSION] A WITH(NOLOCK)
         , [dbo].[SCM_MST_SITE]             B WITH(NOLOCK)
    WHERE  A.SCM_SITE_ID = B.SCM_SITE_ID
    AND    A.CONVERSION_TYPE = ''MTOW''
    AND    A.YYYYMMDD >= ''[@p_from_yyyymm]'' 
    AND    A.YYYYMMDD <= ''[@p_to_yyyymm]'' 
    AND    CASE WHEN N''[@p_division_id]'' = ''ALL'' THEN ''ALL''

/****************************************************************************************************/
/* Program ID  : [DMF0002_GET_WEEK_TO_DAY_DATA]                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/11/15  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/*                                                                                                  */
/****************************************************************************************************/
CREATE PROCEDURE [dbo].[DMF0002_GET_WEEK_TO_DAY_DATA]
  @p_division_id  NVARCHAR(30),
  @p_site_id      NVARCHAR(30)
AS  
  
BEGIN
  SET NOCOUNT ON;

  --DECLARE @v_sql_text       AS NVARCHAR(MAX);  
  
  --SET @v_sql_text = '
    SELECT A.DIVISION_ID
         , B.END_CUSTOMER
      	 , A.SCM_SITE_ID
   --      , SUM(CASE WHEN A.YYYYMMDD = 'MON' THEN A.BUCKET_PER ELSE '' END) AS D_MON
		 --, SUM(CASE WHEN A.YYYYMMDD = 'TUE' THEN A.BUCKET_PER ELSE '' END) AS D_TUE
		 --, SUM(CASE WHEN A.YYYYMMDD = 'WED' THEN A.BUCKET_PER ELSE '' END) AS D_WED
		 --, SUM(CASE WHEN A.YYYYMMDD = 'THU' THEN A.BUCKET_PER ELSE '' END) AS D_THU	
		 --, SUM(CASE WHEN A.YYYYMMDD = 'FRI' THEN A.BUCKET_PER ELSE '' END) AS D_FRI
		 --, SUM(CASE WHEN A.YYYYMMDD = 'SAT' THEN A.BUCKET_PER ELSE '' END) AS D_SAT
		 --, SUM(CASE WHEN A.YYYYMMDD = 'SUN' THEN A.BUCKET_PER ELSE '' END) AS D_SUN
    FROM   [dbo].[DM_MST_BUCKET_CONVERSION] A WITH(NOLOCK)
         , [dbo].[SCM_MST_SITE]             B WITH(NOLOCK)
    WHERE  A.SCM_SITE_ID = B.SCM_SITE_ID
    AND    A.CONVERSION_TYPE = 'WTOD'
    AND    CASE WHEN @p_division_id = 'ALL' THEN 'ALL'
                ELSE A.DIVISION_ID
	       END  IN (SELECT t.c.value('.', 'NVARCHAR(4000)')
                    FROM   (SELECT x = CAST('<t>' + REPLACE(@p_division_id, ',', '</t><t>') + '</t>' AS xml)) b
                    CROSS APPLY x.nodes('/t') t(c)
	               )
    AND    CASE WHEN @p_site_id = 'ALL' THEN 'ALL'
                ELSE A.SCM_SITE_ID
	       END  IN (SELECT t.c.value('.', 'NVARCHAR(4000)')
                    FROM   (SELECT x = CAST('<t>' + REPLACE(@p_site_id, ',', '</t><t>') + '</t>' AS xml)) b
                    CROSS APPLY x.nodes('/t') t(c)
	               )     
	GROUP BY A.DIVISION_ID
           , B.END_CUSTOMER
           , A.SCM_SITE_ID
	;
 
  
								  
END

